window.__reformedWorks["schaff_creeds3_11"] = {"id":"schaff_creeds3_11","a":"Schaff, Philip","t":"The Second Scotch Confession, or the National Covenant. A.D. 1580.","u":"https://ccel.org/ccel/schaff/creeds3","c":[{"t":"The Second Scotch Confession, or the National Covenant. A.D. 1580.","s":[{"t":"","p":["[This Confession is a strong anti-papal appendix to the former, and was subscribed by the King, the Council and Court, at Holyrood House, 1580, by persons of all ranks in 1581, again in 1590 and 1638. The text, with the quaint old spelling, is likewise taken from Dunlop's Collection of Scotch Confessions, Vol. II. pp. 103 sqq. and 811 sqq. The Latin version is said to have been made by John Craig, who wrote the Scotch, and is superior to the one in the Syntagma Confess. (pp. 126 sqq.), which Niemeyer (pp. 357 sqq.) has reproduced.]"]}]}]};
